<section class="dist-page">
<header class="dist-head"><div><h2>Status Pengantaran</h2><p>Pantau progres makanan dari dapur sampai dikonfirmasi sekolah.</p></div><?php if (can('menu.view')): ?><a class="btn btn-ghost" href="<?= e(url('/admin/menu')) ?>"><i class="fa-solid fa-utensils"></i> Menu Sekolah</a><?php endif; ?></header>
<?php if (can('delivery.create')): ?><form class="dist-card" method="post" action="<?= e(url('/admin/pengantaran/baru')) ?>"><?= csrf_field() ?><div class="dist-card-head"><div><h3>Buat pengiriman</h3><p>Pilih menu yang sudah terdaftar untuk sekolah tujuan.</p></div></div><div class="dist-card-body">
<div class="dist-delivery-form">
<label class="dist-field"><span>Sekolah <b>*</b></span><select required class="input" id="schoolSelect" name="school_id"><option value="">Pilih sekolah</option><?php foreach($schools as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></label>
<label class="dist-field"><span>Menu sekolah <b>*</b></span><select required class="input" id="deliveryMenu" name="menu_id"><option value="">Pilih menu</option><?php foreach($allmenus as $mm): ?><option data-school="<?= (int)$mm['school_id'] ?>" value="<?= (int)$mm['id'] ?>"><?= e($mm['school_name']) ?> — <?= e($mm['name']) ?> (<?= e($mm['delivery_date']) ?>)</option><?php endforeach; ?></select></label>
<label class="dist-field"><span>Tanggal pengiriman <b>*</b></span><input required class="input" type="date" name="delivery_date" value="<?= date('Y-m-d') ?>"></label>
<label class="dist-field"><span>Jumlah porsi <b>*</b></span><input required class="input" type="number" name="portions" min="0" value="0"></label>
<label class="dist-field"><span>Distributor / petugas <b>*</b></span><select required class="input" name="distributor_id"><option value="">Pilih karyawan</option><?php foreach($staff as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['full_name']) ?><?= $u['employee_code']?' ('.e($u['employee_code']).')':'' ?></option><?php endforeach; ?></select><?php if(!$staff): ?><small class="u-muted">Belum ada karyawan aktif. Setujui/tambahkan karyawan terlebih dahulu.</small><?php endif; ?></label>
<label class="dist-field dist-description"><span>Catatan awal</span><textarea class="input" name="notes" rows="2" placeholder="Catatan atau kendala"></textarea></label>
</div><div class="dist-actions"><button class="btn btn-primary"><i class="fa-solid fa-truck"></i> Buat pengiriman</button></div></div></form><?php endif; ?>
<section class="dist-card"><div class="dist-card-head"><div><h3>Daftar pengiriman</h3><p><?= count($rows) ?> data terbaru</p></div></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Sekolah & menu</th><th>Tanggal / porsi</th><th>Status</th><th>Estimasi & aktual</th><th>Riwayat / catatan</th></tr></thead><tbody>
<?php foreach($rows as $d): $hs=DB::all('SELECT status,changed_at,note FROM delivery_status_history WHERE delivery_id=? ORDER BY changed_at,id',[$d['id']]); $stateLabel=['preparing'=>'Dalam Pembuatan','in_transit'=>'Dalam Pengantaran','arrived'=>'Sampai di Sekolah','received'=>'Makanan Diterima']; ?><tr>
<td><strong><?= e($d['school_name']) ?></strong><span class="sub"><?= e($d['menu_name']) ?> · <?= e($d['distributor']?:'Petugas belum diatur') ?></span></td><td><?= e(date('d-m-Y',strtotime($d['delivery_date']))) ?><span class="sub"><?= number_format((int)$d['portions']) ?> porsi</span></td>
<td><span class="badge <?= ['preparing'=>'badge-yellow','in_transit'=>'badge-blue','arrived'=>'badge-green','received'=>'badge-green'][$d['status']] ?>"><?= e($stateLabel[$d['status']]??$d['status']) ?></span><?php if (can('delivery.edit')): ?><form class="dist-status-form" method="post" action="<?= e(url('/admin/pengantaran/'.$d['id'].'/status')) ?>"><?= csrf_field() ?><label class="dist-field"><span>Perbarui status</span><select class="input input-sm" name="status"><?php $steps=['preparing','in_transit','arrived','received'];$current=array_search($d['status'],$steps,true);foreach($steps as $idx=>$key):if($idx>=$current&&$idx<=$current+1): ?><option value="<?= $key ?>" <?= $d['status']===$key?'selected':'' ?>><?= e($stateLabel[$key]) ?></option><?php endif;endforeach; ?></select></label><textarea class="input" name="notes" rows="2" placeholder="Catatan kendala (opsional)"><?= e($d['notes']) ?></textarea><button class="btn btn-ghost btn-sm">Simpan status</button></form><?php endif; ?></td>
<td><?php if (can('delivery.edit')): ?><form class="dist-eta-form" method="post" action="<?= e(url('/admin/pengantaran/'.$d['id'].'/eta')) ?>"><?= csrf_field() ?><?php foreach(['eta_start'=>'Mulai persiapan','eta_ready'=>'Selesai dibuat','eta_departure'=>'Keberangkatan','eta_arrival'=>'Estimasi tiba'] as $key=>$label): ?><label class="dist-field"><span><?= e($label) ?></span><input class="input input-sm" type="datetime-local" name="<?= $key ?>" value="<?= $d[$key]?e(str_replace(' ','T',substr($d[$key],0,16))):'' ?>"></label><?php endforeach; ?><button class="btn btn-ghost btn-sm">Simpan estimasi</button></form><?php else: foreach(['eta_start'=>'Mulai persiapan','eta_ready'=>'Selesai dibuat','eta_departure'=>'Keberangkatan','eta_arrival'=>'Estimasi tiba'] as $k=>$lb): ?><span class="sub"><?= e($lb) ?>: <?= $d[$k]?e(date('d-m-Y H:i',strtotime($d[$k]))):'—' ?></span><?php endforeach; endif; ?><span class="sub">Aktual: tiba <?= e($d['arrived_at']?:'—') ?> · diterima <?= e($d['received_at']?:'—') ?></span></td>
<td><div class="dist-timeline"><?php foreach($hs as $h): ?><div class="dist-timeline-item"><b><?= e($stateLabel[$h['status']]??$h['status']) ?></b><span><?= e(date('d-m-Y H:i',strtotime($h['changed_at']))) ?></span><?php if($h['note']): ?><small><?= e($h['note']) ?></small><?php endif; ?></div><?php endforeach; ?></div><?php if($d['notes']): ?><small><?= e($d['notes']) ?></small><?php endif; ?></td></tr>
<?php endforeach; if(!$rows): ?><tr><td class="empty" colspan="5">Belum ada pengiriman. Buat pengiriman dari form di atas.</td></tr><?php endif; ?></tbody></table></div></section></section>

<script>
(()=>{const school=document.getElementById('schoolSelect'),menu=document.getElementById('deliveryMenu');if(!school||!menu)return;const filter=()=>{menu.value='';[...menu.options].forEach((o,i)=>{if(i===0)return;o.hidden=!!school.value&&o.dataset.school!==school.value;});};school.addEventListener('change',filter);filter();})();
</script>
